{"policy":"permit (
    principal is User,
    action == Action::"approveBudget",
    resource is Campaign
)
when {
    principal.roles.contains(Role::"AccountManager") ||
    principal.roles.contains(Role::"CampaignDirector")
};

forbid (
    principal is User,
    action == Action::"approveBudget",
    resource is Campaign
)
when {
    !context.mfaUsed
};

forbid (
    principal is User,
    action == Action::"approveBudget",
    resource is Campaign
)
when {
    (principal.roles.contains(Role::"AccountManager") ||
     principal.roles.contains(Role::"CampaignDirector")) &&
    principal == resource.preparedBy &&
    resource.budget + resource.contingency > context.budgetContingencyThreshold
};

permit (
    principal is User,
    action == Action::"launchCampaign",
    resource is Campaign
)
when {
    principal == resource.advertiser
};

forbid (
    principal is User,
    action == Action::"launchCampaign",
    resource is Campaign
)
when {
    principal != resource.advertiser
};

forbid (
    principal is User,
    action == Action::"launchCampaign",
    resource is Campaign
)
when {
    resource.status != CampaignStatus::"BudgetApproved"
};

forbid (
    principal is User,
    action == Action::"launchCampaign",
    resource is Campaign
)
when {
    !resource.riskLabels.contains(context.requiredRiskLabel)
};"}
